import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"Google Drive 模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/gdrive.md","filePath":"zh-Hans/deep-dive/modules/gdrive.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/modules/gdrive.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="google-drive-模块" tabindex="-1">Google Drive 模块 <a class="header-anchor" href="#google-drive-模块" aria-label="Permalink to “Google Drive 模块”">​</a></h1><p>Google Drive 模块注册 <code>gdrive</code> 远端文件系统。它把仓库存储在一个 Google Drive 文件夹中，通过 Google Drive 公开 API 执行文件操作。模块使用 Google OAuth 认证，不使用第三方服务器或代理。</p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h2><p>模块添加一个 <strong>Google Drive</strong> 设置分组。在选择 Google Drive 作为远端文件系统之前，先配置这些设置：</p><h3 id="连接账户-账户已连接" tabindex="-1">连接账户 / 账户已连接 <a class="header-anchor" href="#连接账户-账户已连接" aria-label="Permalink to “连接账户 / 账户已连接”">​</a></h3><p>这个设置发起 Google 授权流程。授权后，模块把刷新令牌安全地存入 Obsidian 的密钥存储，并按需用它换取短期访问令牌。<strong>Disconnect</strong> 选项向 Google 撤销令牌、把它从密钥存储移除、清除所有缓存的访问令牌，并删除存储的账户标识。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>连接 Google Drive 账户会在 <strong>Obsidian 钥匙串中创建一个名为 <code>sync-engine-gdrive-refresh-token</code> 的新密钥</strong>。这个密钥完全由 Sync Engine 管理，用作换取 Google Drive 访问令牌的刷新令牌。请勿将它用于其他用途。</p></div><h3 id="基目录" tabindex="-1">基目录 <a class="header-anchor" href="#基目录" aria-label="Permalink to “基目录”">​</a></h3><p>这定义 Google Drive 中作为该仓库根目录的文件夹。该值按目录路径规范化。模块启动时留空则默认为 <code>&lt;仓库名&gt;/</code>。指定的文件夹在第一次同步时自动创建。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>基目录是一个由应用管理的命名空间。模块只能看到并操作它通过自己的 Google Drive 集成创建的文件。在 Drive 中手动创建的文件或文件夹、或其他应用创建的文件或文件夹，即使位于配置的基目录内，对这个模块也不可见。它们不会被导入、同步或列出。请不要在这个 Drive 文件夹中手动创建、重命名、移动或维护仓库文件。</p><p>这是 Google 的 <code>drive.file</code> 权限范围带来的结果。模块被有意限制，不授予完整 Drive 访问权限。</p></div><h3 id="删除到垃圾桶" tabindex="-1">删除到垃圾桶 <a class="header-anchor" href="#删除到垃圾桶" aria-label="Permalink to “删除到垃圾桶”">​</a></h3><p>启用时，远端删除的文件被移入 Google Drive 垃圾桶而不是永久移除。禁用时，被删除的文件立即永久清除。注意 Google Drive 通常在 30 天后清空垃圾桶中的条目。</p><h2 id="认证流程" tabindex="-1">认证流程 <a class="header-anchor" href="#认证流程" aria-label="Permalink to “认证流程”">​</a></h2><p>模块使用 <a href="https://developers.google.com/identity/protocols/oauth2/limited-input-device" target="_blank" rel="noreferrer"><strong>Google OAuth 2.0 for TV and Limited-Input Device Applications</strong></a>：</p><ol><li>点击 <strong>Connect</strong> 时，模块向 Google 的设备授权端点请求设备码。</li><li>Obsidian 显示 Google 的验证 URL 和一次性用户码。模块可以复制该码并在浏览器中打开 URL。</li><li>你在该浏览器中登录 Google 并批准请求的访问。授权时请记得勾选以下选项：</li></ol><p><img src="https://img1.tucang.cc/api/image/show/6d34bcb968f679ebfb31c8cd4e6dc354" alt="tick &quot;See, edit, create, and delete only the specific Google Drive files you use with this app.&quot; when authorizing Google Drive" loading="lazy"></p><ol start="4"><li>对话框保持打开期间，Obsidian 轮询 Google 的令牌端点。授权仍在等待时它保持等待，Google 要求放慢轮询间隔时它会退避。</li><li>批准后，Google 返回短期访问令牌、刷新令牌和 OpenID ID 令牌。模块从 ID 令牌提取账户 subject，把刷新令牌存入 Obsidian 的密钥存储，并把访问令牌缓存在内存中。</li><li>之后的 Drive 请求使用缓存的访问令牌。接近过期时，模块用刷新令牌换取新的访问令牌。HTTP 401 的失败请求会触发一次强制刷新并重试。</li></ol><p>使用设备授权是因为 Obsidian 移动端无法可靠地提供常见交互式 OAuth 流程所需的本地浏览器重定向、localhost 监听或桌面式自定义 URL 回调。设备授权把 OAuth 交互保留在普通浏览器中，Obsidian 应用轮询 Google 的端点，因此同一套连接流程在桌面和移动端都能工作。</p><h2 id="权限与范围" tabindex="-1">权限与范围 <a class="header-anchor" href="#权限与范围" aria-label="Permalink to “权限与范围”">​</a></h2><p>模块只请求这几个 OAuth scope：</p><h3 id="drive-file" tabindex="-1"><code>drive.file</code> <a class="header-anchor" href="#drive-file" aria-label="Permalink to “drive.file”">​</a></h3><p>这个 scope 允许模块创建和管理它在 Google Drive 中创建的文件。同步需要这个访问权限来：</p><ul><li>创建基目录和仓库文件</li><li>列出模块自己的文件以发现远端变更</li><li>读取文件内容和元数据</li><li>上传新内容并更新已有文件</li><li>移动或重命名文件</li><li>删除文件（永久删除或移入垃圾桶）</li></ul><p>这个 scope <strong>不</strong>授予对用户 Drive 的一般访问权限。特别是，模块无法发现或同步插件之外创建的文件。授予 <code>drive.file</code> 是刻意的最小权限选择：模块可以管理自己的同步数据，而不会获得读取无关 Drive 文件的权限。</p><h3 id="openid" tabindex="-1"><code>openid</code> <a class="header-anchor" href="#openid" aria-label="Permalink to “openid”">​</a></h3><p><code>openid</code> scope 让 Google 在设备授权期间返回 OpenID Connect ID 令牌。模块读取令牌中稳定的 <code>sub</code> subject 标识并存储为已连接账户的标识。这让 Sync Engine 能识别连接的是哪个 Google 账户，并区分多个账户连接，使不同 Google 账户的同步记录互不干扰；它不读取用户资料，也不请求宽泛的身份权限。</p><h2 id="文件元数据" tabindex="-1">文件元数据 <a class="header-anchor" href="#文件元数据" aria-label="Permalink to “文件元数据”">​</a></h2><p>Google Drive 把文件元数据存储为文件资源上的 <code>appProperties</code>。文件 <code>meta</code> 非空时，<code>write()</code> 和 <code>writeStream()</code> 会带上 <code>appProperties</code>。存在时，<code>stat()</code> 和 <code>list()</code> 把 <code>appProperties</code> 作为文件的 <code>meta</code> 返回。</p><h2 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to “隐私政策”">​</a></h2><p>最后更新于 <strong>2026 年 8 月 23 日</strong>。</p><h3 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h3><p>本隐私政策说明 Obsidian 的 Sync Engine 插件与 Google Drive 模块（下称&quot;插件&quot;）在你连接 Google Drive 账户时如何处理你的数据。插件是 MIT 协议授权的开源软件。</p><h3 id="我们收集的数据" tabindex="-1">我们收集的数据 <a class="header-anchor" href="#我们收集的数据" aria-label="Permalink to “我们收集的数据”">​</a></h3><p><strong>我们不收集任何数据。</strong> 插件没有遥测、没有分析、没有远程日志服务，也没有后端服务器。任何关于你、你的文件或你的使用情况的信息都不会离开你的本地设备。</p><h3 id="你的数据如何被处理" tabindex="-1">你的数据如何被处理 <a class="header-anchor" href="#你的数据如何被处理" aria-label="Permalink to “你的数据如何被处理”">​</a></h3><p><strong>Google 账户连接</strong>：</p><p>点击 &quot;Connect&quot; 时，插件在你的设备与 Google 服务器之间直接发起 Google 设备授权流程。插件只请求以下 scope：</p><ul><li><code>drive.file</code>：访问由插件创建的文件。插件之外创建的文件对它不可见，即使在配置的基目录内。</li><li><code>openid</code>：提供稳定的 Google 账户 subject 标识，让插件能够识别连接并去重</li></ul><p><strong>令牌存储</strong>：</p><p>OAuth 刷新令牌只存储在你本地设备的 Electron 加密密钥存储中。令牌从不传输给任何第三方，从不记录日志，也从不出现在崩溃报告或诊断信息中。</p><p><strong>文件操作</strong>：</p><p>所有同步操作都由你手动触发或调度。文件读写直接发生在你的本地 Obsidian 仓库与 Google Drive 之间，经 Google 的 API 完成。没有任何中间服务器参与。</p><p><strong>数据保留</strong>：</p><p>你的数据只存在于你的本地设备和你的 Google Drive 账户中。点击 &quot;Disconnect&quot; 时，插件：</p><ol><li>向 Google 撤销 OAuth 令牌</li><li>从 Electron 密钥存储删除所有已存储的令牌</li></ol><p>断开连接后，你的设备上不会残留任何 Google 账户连接的痕迹。</p><h3 id="第三方" tabindex="-1">第三方 <a class="header-anchor" href="#第三方" aria-label="Permalink to “第三方”">​</a></h3><p>涉及的唯一第三方服务是 Google 的 OAuth 和 Drive API，由你直接授权。除使用其公开 API 外，我们与 Google 没有任何关系。我们不向任何实体共享、出售或转移任何数据。</p><h3 id="你的权利" tabindex="-1">你的权利 <a class="header-anchor" href="#你的权利" aria-label="Permalink to “你的权利”">​</a></h3><p>你拥有完全的控制：</p><ul><li>所有数据都在你的本地设备上，随时可以检查</li><li>点击 &quot;Disconnect&quot; 立即清除所有本地凭据</li><li>随时在 <code>https://myaccount.google.com/permissions</code> 撤销访问</li><li>无论插件状态如何，你的文件都保留在你的 Google Drive 中</li></ul><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to “变更”">​</a></h3><p>本政策的更新将发布在插件的 GitHub 仓库和 <code>https://sync.consensia.cc</code>。变更后的继续使用视为接受。</p><h3 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to “联系方式”">​</a></h3><p>隐私相关问题请在我们 GitHub 仓库中提交 issue。</p><h2 id="服务条款" tabindex="-1">服务条款 <a class="header-anchor" href="#服务条款" aria-label="Permalink to “服务条款”">​</a></h2><p>最后更新于 <strong>2026 年 8 月 23 日</strong>。</p><h3 id="接受条款" tabindex="-1">接受条款 <a class="header-anchor" href="#接受条款" aria-label="Permalink to “接受条款”">​</a></h3><p>安装或使用 Obsidian 的 Sync Engine 插件与 Google Drive 模块（下称&quot;插件&quot;），即表示你同意这些条款。不同意请立即卸载插件。</p><h3 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to “许可”">​</a></h3><p>插件以 MIT 协议提供。你可以按该协议条款自由使用、修改和分发它。</p><h3 id="无担保" tabindex="-1">无担保 <a class="header-anchor" href="#无担保" aria-label="Permalink to “无担保”">​</a></h3><p><strong>插件按&quot;现状&quot;提供，不附带任何形式的担保，无论是明示还是暗示，包括但不限于对适销性、特定用途适用性和不侵权的担保。作者和版权持有人不对因使用插件产生的任何索赔、损害或其他责任负责，包括数据丢失、同步失败或 Google Drive API 变更。</strong></p><h3 id="用户责任" tabindex="-1">用户责任 <a class="header-anchor" href="#用户责任" aria-label="Permalink to “用户责任”">​</a></h3><p>你独自负责：</p><ul><li>维护 Google 账户凭据的安全</li><li>了解你选择同步的数据</li><li>独立于插件备份重要文件</li><li>连接 Drive 账户时遵守 Google 的服务条款</li><li>确保本地设备的 Electron 密钥存储保持安全</li></ul><h3 id="可接受的使用" tabindex="-1">可接受的使用 <a class="header-anchor" href="#可接受的使用" aria-label="Permalink to “可接受的使用”">​</a></h3><p>不得使用插件：</p><ul><li>违反 Google 的 API 服务条款</li><li>访问你不拥有或未获授权的账户</li><li>规避 Google Drive 的存储或速率限制</li><li>经同步文件分发恶意软件或非法内容</li></ul><h3 id="第三方服务" tabindex="-1">第三方服务 <a class="header-anchor" href="#第三方服务" aria-label="Permalink to “第三方服务”">​</a></h3><p>插件与 Google 的 OAuth 和 Drive API 交互。这些服务受 Google 自己的服务条款和隐私政策约束。我们无法控制 Google 的服务，对其可用性、变更或终止不承担责任。</p><h3 id="断开连接与终止" tabindex="-1">断开连接与终止 <a class="header-anchor" href="#断开连接与终止" aria-label="Permalink to “断开连接与终止”">​</a></h3><p>你可以随时点击插件设置中的 &quot;Disconnect&quot; 或卸载插件来终止使用。我们保留随时停止开发或分发插件的权利，恕不另行通知。</p><h3 id="责任限制" tabindex="-1">责任限制 <a class="header-anchor" href="#责任限制" aria-label="Permalink to “责任限制”">​</a></h3><p><strong>在法律允许的最大范围内，无论基于何种责任理论，作者或贡献者均不对任何间接、附带、特殊、后果性或惩罚性损害负责，包括利润损失、数据丢失或业务中断。</strong></p><h3 id="适用法律" tabindex="-1">适用法律 <a class="header-anchor" href="#适用法律" aria-label="Permalink to “适用法律”">​</a></h3><p>本插件由位于世界各地多个司法管辖区的贡献者以自愿、非商业方式开发和维护。没有单一的适用法律。</p><p>这些条款应依据国际法的一般原则和插件分发所依据的 MIT 协议来解释。</p><h3 id="变更-1" tabindex="-1">变更 <a class="header-anchor" href="#变更-1" aria-label="Permalink to “变更”">​</a></h3><p>我们可能随时更新这些条款。变更在 GitHub 仓库中发布后生效。继续使用视为接受。</p><h3 id="联系方式-1" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式-1" aria-label="Permalink to “联系方式”">​</a></h3><p>条款相关问题请在我们 GitHub 仓库中提交 issue。</p>`,82)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};